#include <bits/stdc++.h>
using namespace std;

const int MOD_A=998244353;
const int MOD_B=1000000007;
long long total_num;
int num_digits[15], base_array[15], result;

long long get_num(int *arr, int len){
    long long res=0;
    for (int i=1; i<=len; i++)
        res=res*10+arr[i];
    return res;
}

long long calc_rank(int *arr, int len){
    long long count=0;
    for (int d=1; d<=*num_digits; d++){
        for (int i=1; i<=min(len,d); i++){
            for (int j=(i==1?1:0); j<arr[i]; j++){
                long long left=0, right=0;
                for (int p=1; p<i; p++)
                    left=right=left*10+arr[p];
                left=right=left*10+j;
                for (int p=i+1; p<=d; p++)
                    left=left*10, right=right*10+9;
                right=min(right, total_num);
                if (left<=right)
                    count+=right-left+1;
            }
        }
        if (d<=len) ++count;
    }
    return count;
}

int computeF(int *arr, int len){
    return ((-get_num(arr,len)+calc_rank(arr,len))%MOD_A+MOD_A)%MOD_A;
}

int diff_vals[15];
int q1_array[1000010], q2_array[1000010];
long long q2_sum[1000010];

void dfs_range(int start, int end, int *q, int v){
    if (start==end){
        for (int i=0; i<=9; i++)
            q[++*q]=(v+1LL*i*diff_vals[start])%MOD_A;
        return;
    }
    for (int i=0; i<=9; i++)
        dfs_range(start+1, end, q, (v+1LL*i*diff_vals[start])%MOD_A);
}

void perform_update(int len, int idx, int val){
    int backup[15];
    memcpy(backup, num_digits, sizeof(num_digits));
    num_digits[idx]=val;
    for (int p=idx+1; p<=len; p++) num_digits[p]=0;
    int baseVal=computeF(num_digits,len);
    for (int p=idx+1; p<=len; p++){
        num_digits[p]=1;
        diff_vals[p]=(computeF(num_digits,len)+MOD_A-baseVal)%MOD_A;
        num_digits[p]=0;
    }
    if (len-idx==0){
        result=(result+baseVal)%MOD_B;
        return;
    }
    if (len-idx==1){
        for (int p=0; p<=9; p++)
            result=(result+(baseVal+1LL*p*diff_vals[len])%MOD_A)%MOD_B;
        return;
    }
    int mid=(len+idx)/2;
    *q1_array=0; *q2_array=0;
    dfs_range(idx+1, mid, q1_array, baseVal);
    dfs_range(mid+1, len, q2_array, 0);
    std::sort(q2_array+1, q2_array+*q2_array+1);
    long long sumQ2=0;
    for (int i=1; i<=*q2_array; i++)
        sumQ2=(sumQ2+q2_array[i])%MOD_B;
    for (int i=1; i<=*q1_array; i++){
        int p=lower_bound(q2_array+1, q2_array+*q2_array+1, MOD_A - q1_array[i]) - q2_array;
        result=(result+sumQ2+1LL*(*q2_array)*q1_array[i])%MOD_B;
        result=(result+1LL*((*q2_array)-p+1)*(MOD_B-MOD_A))%MOD_B;
    }
}

int main(){
    scanf("%lld", &total_num);
    long long m=total_num;
    for (*num_digits=0; m; m/=10) num_digits[++*num_digits]=m%10;
    std::reverse(num_digits+1, num_digits+*num_digits+1);
    for (int d=1; d<=*num_digits; d++){
        for (int i=1; i<=d; i++){
            int l=(i==1?1:0);
            int r=(d==*num_digits?num_digits[i]-1:9);
            for (int j=l; j<=r; j++)
                if (j!=num_digits[i]) perform_update(d, i, j);
        }
        result=(result+computeF(num_digits, d))%MOD_B;
    }
    printf("%d\n", result);
}
